before.content:
.trust-panel code { padding: .65rem; border-radius: .5rem; background: #e8ebf1; overflow-wrap: anywhere; }
.trust-panel > div { display: flex; flex-wrap: wrap; gap: .55rem; }
.settings-section { max-width: 48rem; }
.profile-list { display: grid; gap: 1rem; }
.profile-editor { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; padding: 1.2rem; border-radius: .9rem; background: white; box-shadow: 0 10px 34px rgba(32,43,67,.05); }
.profile-editor > header, .profile-actions, .profile-editor > .warning, .profile-editor > .error, .profile-collection { grid-column: 1 / -1; }

after.content:
.trust-panel code { padding: .65rem; border-radius: .5rem; background: #e8ebf1; overflow-wrap: anywhere; }
.trust-panel > div { display: flex; flex-wrap: wrap; gap: .55rem; }
.settings-section { max-width: 48rem; }
.relay-management { display: grid; gap: 1rem; }
.relay-management > label, .relay-management .trust-panel label { display: grid; gap: .4rem; }
.relay-management input { min-width: 0; padding: .6rem .7rem; border: 1px solid #b9c1cf; border-radius: .55rem; background: transparent; color: inherit; }
.relay-management .resource-list article { align-items: center; }
.profile-list { display: grid; gap: 1rem; }
.profile-editor { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; padding: 1.2rem; border-radius: .9rem; background: white; box-shadow: 0 10px 34px rgba(32,43,67,.05); }
.profile-editor > header, .profile-actions, .profile-editor > .warning, .profile-editor > .error, .profile-collection { grid-column: 1 / -1; }
